const body = $input.first().json.body || $input.first().json;
const event = (body.event || '').toLowerCase();

if (event !== 'messages.upsert') {
  return [{ json: { skip: true, skipReason: 'event_not_supported' } }];
}

const data = body.data || {};
const key = data.key || {};
const message = data.message || {};

if (key.fromMe) {
  return [{ json: { skip: true, skipReason: 'from_me' } }];
}

const remoteJid = key.remoteJid || '';
if (!remoteJid || remoteJid.includes('@broadcast') || remoteJid.includes('status@broadcast') || remoteJid.includes('@g.us')) {
  return [{ json: { skip: true, skipReason: 'jid_not_supported' } }];
}

const messageType = (data.messageType || Object.keys(message)[0] || '').trim();
const allowedTypes = ['conversation', 'extendedTextMessage'];
if (!allowedTypes.includes(messageType)) {
  return [{ json: { skip: true, skipReason: 'message_type_not_supported' } }];
}

const textRaw = message.conversation || message.extendedTextMessage?.text || '';
const text = textRaw.trim();
if (!text) {
  return [{ json: { skip: true, skipReason: 'empty_text' } }];
}

const messageTimestamp = Number(data.messageTimestamp || 0);
const nowSeconds = Math.floor(Date.now() / 1000);
if (messageTimestamp > 0 && Math.abs(nowSeconds - messageTimestamp) > 600) {
  return [{ json: { skip: true, skipReason: 'stale_message' } }];
}

const pushName = data.pushName || body.pushName || 'Cliente';
const instanceName = body.instance || 'DKO-Muebles';
const messageId = key.id || `${remoteJid}:${messageTimestamp || nowSeconds}:${text.slice(0, 32)}`;
const phone = remoteJid.replace('@s.whatsapp.net', '').replace('@g.us', '');

return [{
  json: {
    skip: false,
    phone,
    remoteJid,
    text,
    pushName,
    instanceName,
    messageId,
    messageTimestamp,
  }
}];

const historialRaw = $input.first().json.value || null;
let historial = [];

try {
  if (historialRaw) historial = JSON.parse(historialRaw);
} catch (e) {
  historial = [];
}

if (!Array.isArray(historial)) historial = [];
if (historial.length > 10) historial = historial.slice(-10);

const parsed = $('Parsear Mensaje').first().json;

const systemInstruction = `Eres el asistente de DKO Mueblería.
Tu ÚNICA función es clasificar la intención del usuario.

REGLAS:
1. Si el usuario saluda o hace pregunta general -> PEDIR_INFO
2. Si menciona un mueble o producto concreto -> BUSCAR_PRODUCTO
3. Si quiere comprar, pagar, hablar con alguien -> ESCALAR_HUMANO

Responde solo con JSON válido con esta forma:
{"accion":"PEDIR_INFO|BUSCAR_PRODUCTO|ESCALAR_HUMANO","query":string|null,"respuesta":string|null}`;

const geminiPayload = {
  system_instruction: { parts: [{ text: systemInstruction }] },
  contents: [{ parts: [{ text: `Historial: ${JSON.stringify(historial)}\nMensaje: ${parsed.text}` }] }],
  generationConfig: {
    temperature: 0.1,
    maxOutputTokens: 300,
    responseMimeType: 'application/json',
  },
};

return [{
  json: {
    phone: parsed.phone,
    remoteJid: parsed.remoteJid,
    pushName: parsed.pushName,
    instanceName: parsed.instanceName,
    text: parsed.text,
    historial,
    geminiPayload,
  }
}];

const geminiRaw = $input.first().json;
let rawText = geminiRaw.candidates?.[0]?.content?.parts?.[0]?.text || '{}';

rawText = rawText.replace(/```json/g, '').replace(/```/g, '').trim();

let decision;
try {
  decision = JSON.parse(rawText);
} catch (e) {
  decision = {
    accion: 'PEDIR_INFO',
    query: null,
    respuesta: '¡Hola! Bienvenido a DKO Mueblería. ¿En qué producto te puedo ayudar?',
  };
}

const ctx = $('Preparar Contexto').first().json;
const allowedActions = ['BUSCAR_PRODUCTO', 'PEDIR_INFO', 'ESCALAR_HUMANO'];
const accionRaw = (decision.accion || '').toString().toUpperCase().trim();
const accion = allowedActions.includes(accionRaw) ? accionRaw : 'PEDIR_INFO';
const query = accion === 'BUSCAR_PRODUCTO'
  ? ((decision.query || ctx.text || '').toString().trim() || ctx.text)
  : null;

let respuesta = typeof decision.respuesta === 'string' ? decision.respuesta.trim() : null;
if (!respuesta && accion === 'PEDIR_INFO') {
  respuesta = '¡Hola! Bienvenido a DKO Mueblería. ¿En qué producto te puedo ayudar?';
}
if (!respuesta && accion === 'ESCALAR_HUMANO') {
  respuesta = 'Claro, en un momento uno de nuestros asesores de DKO Mueblería se pondrá en contacto contigo.';
}

return [{
  json: {
    accion,
    query,
    respuesta,
    phone: ctx.phone,
    remoteJid: ctx.remoteJid,
    pushName: ctx.pushName,
    instanceName: ctx.instanceName,
    text: ctx.text,
    historial: ctx.historial,
  }
}];

