const ctx = $input.first().json;
const accion = (ctx.accion || '').toUpperCase();

let responseText = '';

if (accion === 'PEDIR_INFO') {
  responseText = ctx.respuesta || '¡Hola! Bienvenido a DKO Mueblería. ¿En qué producto te puedo ayudar?';
} else if (accion === 'ESCALAR_HUMANO') {
  responseText = ctx.respuesta || 'Claro, en un momento uno de nuestros asesores de DKO Mueblería se pondrá en contacto contigo. ¡Gracias por tu paciencia!';
} else {
  responseText = 'Gracias por escribirnos. Un asesor de DKO Mueblería te atenderá en breve.';
}

return [{
  json: {
    responseText,
    phone: ctx.phone,
    remoteJid: ctx.remoteJid,
    instanceName: ctx.instanceName,
    text: ctx.text,
    historial: ctx.historial || [],
    accion: accion || 'PEDIR_INFO',
  }
}];

const item = $input.first().json;
const historial = item.historial || [];

historial.push({ role: 'cliente', mensaje: item.text });
historial.push({ role: 'bot', mensaje: item.responseText });

const historialActualizado = historial.slice(-10);

// Payload formato Evolution API v2
const evolutionPayload = {
  number: item.remoteJid,
  text: item.responseText,
  delay: 1200,
  presence: 'composing'
};

return [{
  json: {
    ...item,
    historialActualizado,
    evolutionPayload
  }
}];

